func (this *ToolItem) _setImage(imageLike ImageLike) {
	var image *Image
	if imageLike != nil {
		image = imageLike.AsImage()
	}
	_ = image
	if (this.style & SEPARATOR) != 0 {
		return
	}
	this.currentImage = image
	if image != (nil) {
		var imageList *ImageList = this.parent.imageList
		if imageList == (nil) {
			this.parent.imageList = NewImageList()
			imageList = this.parent.imageList
		}
		var imageIndex int32 = imageList.IndexOf(image)
		if imageIndex == -1 {
			imageIndex = imageList.Add(image)
		} else {
			imageList.Put(imageIndex, image)
		}
		if gtk.GTKGTK4 {
			this.Gtk_widget_show(this.imageBoxHandle)
			var pixbuf int64 = ImageListCreatePixbufImage(image)
			var texture int64 = gtk.GDKGdk_texture_new_for_pixbuf(pixbuf)
			gtk.OSG_object_unref(pixbuf)
			var bounds *Rectangle = image.GetBounds()
			var paintable int64 = gtk.OSSwt_scaled_paintable_new(texture, bounds.Width, bounds.Height)
			gtk.OSG_object_unref(texture)
			gtk.GTK4Gtk_picture_set_paintable(this.imageHandle, paintable)
			gtk.OSG_object_unref(paintable)
		} else {
			gtk.GTK3Gtk_image_set_from_surface(this.imageHandle, imageList.GetSurface(imageIndex))
		}
	} else {
		if gtk.GTKGTK4 {
			gtk.GTK4Gtk_picture_set_paintable(this.imageHandle, int64(0))
			this.Gtk_widget_hide(this.imageBoxHandle)
		} else {
			gtk.GTK3Gtk_image_set_from_surface(this.imageHandle, int64(0))
		}
	}
	this.RecreateMenuProxy()
	this.parent.Relayout()
}

