func (this *ToolItem) ShowWidget(index int32) {
	if gtk.GTKGTK4 {
		if index == 0 {
			gtk.GTK4Gtk_box_prepend(this.parent.Handle, this.Handle)
		} else {
			if index < 0 {
				gtk.GTK4Gtk_box_append(this.parent.Handle, this.Handle)
			} else {
				for sibling := int64(gtk.GTK4Gtk_widget_get_first_child(this.parent.Handle)); sibling != 0; sibling = gtk.GTK4Gtk_widget_get_next_sibling(sibling) {
					if index == 1 {
						gtk.GTK4Gtk_box_insert_child_after(this.parent.Handle, this.Handle, sibling)
						break
					}
					index--
				}
			}
		}
	} else {
		if this.Handle != 0 {
			this.Gtk_widget_show(this.Handle)
		}
		if this.labelHandle != 0 {
			this.Gtk_widget_show(this.labelHandle)
		}
		if this.imageHandle != 0 {
			this.Gtk_widget_show(this.imageHandle)
		}
		gtk.GTK3Gtk_toolbar_insert(this.parent.Handle, this.Handle, index)
	}
}

func (this *ToolItem) UpdateStyle() {
	if (this.style & SEPARATOR) != 0 {
		return
	}
	if this.provider == 0 {
		this.provider = gtk.GTKGtk_css_provider_new()
		if (this.style & DROP_DOWN) != 0 {
			if gtk.GTKGTK4 {
				var context int64 = gtk.GTKGtk_widget_get_style_context(this.boxHandle)
				gtk.GTKGtk_style_context_add_provider(context, this.provider, gtk.GTKGTK_STYLE_PROVIDER_PRIORITY_APPLICATION)
				context = gtk.GTKGtk_widget_get_style_context(this.arrowHandle)
				gtk.GTKGtk_style_context_add_provider(context, this.provider, gtk.GTKGTK_STYLE_PROVIDER_PRIORITY_APPLICATION)
			} else {
				var box int64 = gtk.GTK3Gtk_bin_get_child(this.Handle)
				var list int64 = gtk.GTK3Gtk_container_get_children(box)
				for i := int32(0); i < 2; i++ {
					var child int64 = gtk.OSG_list_nth_data(list, i)
					var context int64 = gtk.GTKGtk_widget_get_style_context(child)
					gtk.GTKGtk_style_context_add_provider(context, this.provider, gtk.GTKGTK_STYLE_PROVIDER_PRIORITY_APPLICATION)
				}
				gtk.OSG_list_free(list)
			}
		} else {
			var context int64
			if gtk.GTKGTK4 {
				context = gtk.GTKGtk_widget_get_style_context(this.Handle)
			} else {
				var child int64 = gtk.GTK3Gtk_bin_get_child(this.Handle)
				context = gtk.GTKGtk_widget_get_style_context(child)
			}
			gtk.GTKGtk_style_context_add_provider(context, this.provider, gtk.GTKGTK_STYLE_PROVIDER_PRIORITY_APPLICATION)
		}
		gtk.OSG_object_unref(this.provider)
	}
	var css string = ""
	if this.foreground != (nil) {
		css += fmt.Sprintf("button { color: %s; }", this.display.Gtk_rgba_to_css_string(this.foreground.Handle))
	} else {
		css += this.parent.cssForeground
	}
	if this.background != (nil) {
		css += fmt.Sprintf("button { background-image: none; background-color: %s; }", this.display.Gtk_rgba_to_css_string(this.background.Handle))
	}
	if gtk.GTKGTK4 {
		gtk.GTK4Gtk_css_provider_load_from_data(this.provider, gtk.ConverterWcsToMbcs(css, true), int64(-1))
	} else {
		gtk.GTK3Gtk_css_provider_load_from_data(this.provider, gtk.ConverterWcsToMbcs(css, true), int64(-1), nil)
	}
}

func (this *ToolItem) getNameText_() string {
	var nameText string = this.Item.getNameText_()
	var data any = this.GetData()
	if !jrt.IsNil(data) {
		return fmt.Sprintf("text: '%s', data: %v", nameText, data)
	}
	return nameText
}

func (this *ToolItem) dpiChanged_(object int64, arg0 int64) int64 {
	this.Item.dpiChanged_(object, arg0)
	if this.image != (nil) {
		this.image.Internal_gtk_refreshImageForZoom()
		this.impl.setImageOnItem_(this.image)
	}
	if this.hotImage != (nil) {
		this.hotImage.Internal_gtk_refreshImageForZoom()
		this.SetHotImage(this.hotImage)
	}
	if this.disabledImage != (nil) {
		this.disabledImage.Internal_gtk_refreshImageForZoom()
		this.SetDisabledImage(this.disabledImage)
	}
	return int64(0)
}

func (this *ToolItem) RecreateMenuProxy() {
	if (this.style&DROP_DOWN) != 0 || this.proxyMenuItem != 0 {
		if gtk.GTKGTK4 {
		} else {
			this.proxyMenuItem = int64(0)
			this.proxyMenuItem = gtk.GTK3Gtk_tool_item_retrieve_proxy_menu_item(this.Handle)
		}
	}
}

func ToolItemCheckStyle(style int32) int32 {
	return WidgetCheckBits(style, PUSH, CHECK, RADIO, SEPARATOR, DROP_DOWN, 0)
}

func upcastToolBarToComposite(x *ToolBar) *Composite {
	if x == nil {
		return nil
	}
	return &x.Composite
}
